Complete local Rust example; the app itself does not execute it:
```rust
use std::sync::Arc;

fn main() {
    let mut value = Arc::new(7);
    let other = Arc::clone(&value);
    println!("{}", Arc::get_mut(&mut value).is_some());
    drop(other);
    println!("{}", Arc::get_mut(&mut value).is_some());
}
```

